     1→// FreeLang v2 - C Compiler bridge
     2→// Calls GCC, returns structured result. No human output.
     3→
     4→import { execSync } from 'child_process';
     5→import { writeFileSync, unlinkSync, existsSync, mkdirSync } from 'fs';
     6→import { join } from 'path';
     7→import { CompileResult } from './types';
     8→
     9→const OUT_DIR = join(process.cwd(), '.freelang-ai-out');
    10→
    11→export class Compiler {
    12→  private outDir: string;
    13→
    14→  constructor(outDir?: string) {
    15→    this.outDir = outDir ?? OUT_DIR;
    16→    if (!existsSync(this.outDir)) {
    17→      mkdirSync(this.outDir, { recursive: true });
    18→    }
    19→  }
    20→
    21→  compile(cCode: string, name: string): CompileResult {
    22→    const cPath = join(this.outDir, `${name}.c`);
    23→    const binPath = join(this.outDir, name);
    24→
    25→    try {
    26→      writeFileSync(cPath, cCode);
    27→      const output = execSync(`gcc -O2 -o "${binPath}" "${cPath}" -lm 2>&1`, {
    28→        encoding: 'utf-8',
    29→        timeout: 10_000,
    30→      });
    31→      return { ok: true, c_code: cCode, binary_path: binPath, gcc_output: output };
    32→    } catch (e: unknown) {
    33→      const msg = e instanceof Error ? (e as any).stderr ?? e.message : String(e);
    34→      return { ok: false, c_code: cCode, error: msg };
    35→    }
    36→  }
    37→
    38→  run(binPath: string): { ok: boolean; stdout: string; exit_code: number } {
    39→    try {
    40→      const stdout = execSync(`"${binPath}"`, { encoding: 'utf-8', timeout: 5_000 });
    41→      return { ok: true, stdout: stdout.trim(), exit_code: 0 };
    42→    } catch (e: unknown) {
    43→      const err = e as any;
    44→      return { ok: false, stdout: err.stdout ?? '', exit_code: err.status ?? 1 };
    45→    }
    46→  }
    47→
    48→  compileAndRun(cCode: string, name: string): { compile: CompileResult; run?: { ok: boolean; stdout: string; exit_code: number } } {
    49→    const cr = this.compile(cCode, name);
    50→    if (!cr.ok || !cr.binary_path) return { compile: cr };
    51→    const rr = this.run(cr.binary_path);
    52→    return { compile: cr, run: rr };
    53→  }
    54→
    55→  cleanup(name: string): void {
    56→    const cPath = join(this.outDir, `${name}.c`);
    57→    const binPath = join(this.outDir, name);
    58→    try { if (existsSync(cPath)) unlinkSync(cPath); } catch { /* ignore */ }
    59→    try { if (existsSync(binPath)) unlinkSync(binPath); } catch { /* ignore */ }
    60→  }
    61→}
