     1→// FreeLang v2 VM - Stack-based IR interpreter
     2→// Extended: Now supports strings for Project Ouroboros (Self-Hosting)
     3→// Phase 19: Now supports user-defined functions
     4→// Phase 21: Now supports type-safe execution with runtime validation
     5→// Phase J: Now supports async/await with SimplePromise
     6→
     7→import { Op, Inst, VMResult, VMError } from './types';
     8→import { Iterator, IteratorEngine } from './engine/iterator';
     9→import { FunctionRegistry, LocalScope } from './parser/function-registry';
    10→import { FunctionTypeChecker } from './analyzer/type-checker';
    11→import { TypeParser } from './cli/type-parser';
    12→import { NativeFunctionRegistry, NativeFunctionConfig } from './vm/native-function-registry';
    13→import { IRGenerator } from './codegen/ir-generator';
    14→import { registerStdlibFunctions } from './stdlib-builtins';
    15→import { registerTCPFunctions } from './stdlib/net/tcp-native';
    16→import { registerSystemExtendedFunctions } from './stdlib-system-extended';
    17→import { registerSQLiteNativeFunctions } from './stdlib/sqlite-native';
    18→import { registerFsExtendedFunctions } from './stdlib-fs-extended';
    19→import { trackFunctionCall, isHotFunction, generateHotspotReport } from './phase-jit/hotspot-detector';
    20→import { SimplePromise } from './runtime/simple-promise';
    21→import { registerInsightFunctions } from './stdlib/insight-builtins';
    22→import { registerProfilerFunctions } from './stdlib/profiler-builtins';
    23→import { registerORMNativeFunctions } from './stdlib/orm-native';
    24→import {
    25→  registerNativeQueryFunctions,
    26→  cacheQueryBefore,
    27→  cacheQueryAfter,
    28→  CachedQueryConfig,
    29→} from './stdlib-native-query';
    30→
    31→const MAX_CYCLES = 100_000;
    32→const MAX_STACK  = 10_000;
    33→
    34→// ── Result<T, E> & Option<T> 타입 정의 ──
    35→export interface ResultOk<T = any> {
    36→  tag: 'ok';
    37→  val: T;
    38→}
    39→
    40→export interface ResultErr<E = any> {
    41→  tag: 'err';
    42→  val: E;
    43→}
    44→
    45→export interface OptionSome<T = any> {
    46→  tag: 'some';
    47→  val: T;
    48→}
    49→
    50→export interface OptionNone {
    51→  tag: 'none';
    52→}
    53→
    54→export type Result<T = any, E = any> = ResultOk<T> | ResultErr<E>;
    55→export type Option<T = any> = OptionSome<T> | OptionNone;
    56→
    57→export interface TypeWarning {
    58→  functionName: string;
    59→  message: string;
    60→  timestamp: Date;
    61→  paramName?: string;
    62→  expectedType?: string;
    63→  receivedType?: string;
    64→}
    65→
    66→export class VM {
    67→  private stack: (number | Iterator | string | number[] | object | Result | Option)[] = [];
    68→  private vars: Map<string, number | number[] | Iterator | string | object | Result | Option> = new Map();
    69→  private pc = 0;
    70→  private cycles = 0;
    71→  private callStack: number[] = [];  // for CALL/RET
    72→  private callbackRegistry: Map<number, Inst[]> = new Map();  // callback_id -> bytecode
    73→  private nextCallbackId = 0;
    74→  private functionRegistry?: FunctionRegistry;  // Phase 19: user-defined functions
    75→  private currentScope?: LocalScope;  // Phase 19: variable scoping
    76→  private currentLambda?: any;  // B7 수정: 현재 구성 중인 lambda 객체
    77→  private typeChecker = new FunctionTypeChecker();  // Phase 21: type-safe execution
    78→  private typeWarnings: TypeWarning[] = [];  // Phase 21: track type warnings
    79→  private nativeFunctionRegistry = new NativeFunctionRegistry();  // Phase 3: FFI native functions
    80→  private tryStack: Array<{ catchOffset: number; errorVar: string }> = [];  // Phase I: Exception handling
    81→
    82→  // Performance optimization (Phase C): Hot path instruction handlers
    83→  private instructionHandlers = new Map<Op, (inst: Inst, program: Inst[]) => void>();
    84→  private hotPathOps = new Set<Op>([Op.PUSH, Op.POP, Op.ADD, Op.SUB, Op.MUL, Op.DIV, Op.LOAD, Op.STORE]);
    85→  private handlersInitialized = false;
    86→
    87→  constructor(functionRegistry?: FunctionRegistry) {
    88→    this.functionRegistry = functionRegistry;
    89→    // Register stdlib functions (math, string, array, map, io, etc.)
    90→    registerStdlibFunctions(this.nativeFunctionRegistry);
    91→    // Phase 3 Level 3: Register TCP native functions
    92→    registerTCPFunctions(this.nativeFunctionRegistry);
    93→    // Phase C: Register system extended functions (event, logging, scheduler, cache, validation, config)
    94→    registerSystemExtendedFunctions(this.nativeFunctionRegistry);
    95→    // Phase D: Register SQLite native functions
    96→    registerSQLiteNativeFunctions(this.nativeFunctionRegistry);
    97→    // Phase D: Register file system extended functions
    98→    registerFsExtendedFunctions(this.nativeFunctionRegistry);
    99→    // Phase 26: Set VM reference for higher-order functions
   100→    this.nativeFunctionRegistry.setVM(this);
   101→    // Self-Monitoring Kernel: insight_enter/exit/report/json/dashboard/gogs
   102→    registerInsightFunctions(this.nativeFunctionRegistry);
   103→    // Self-Profiling Runtime: profiler_enter/exit/report/flame_json/send_gogs
   104→    registerProfilerFunctions(this.nativeFunctionRegistry);
   105→    // Compile-Time-ORM: orm_table_init/insert/find_all/find_one/update/delete/count
   106→    registerORMNativeFunctions(this.nativeFunctionRegistry);
   107→    // Native-State-Hydration: query_cache_get/set/del/fresh/stale/stats/clear
   108→    registerNativeQueryFunctions(this.nativeFunctionRegistry);
   109→  }
   110→
   111→  /**
   112→   * Phase 21: Infer type of a value
   113→   */
   114→  private inferType(value: any): string {
   115→    return TypeParser.inferType(value);
   116→  }
   117→
   118→  /**
   119→   * Phase 21: Infer types of stack top N values
   120→   */
   121→  private inferStackTypes(count: number): string[] {
   122→    const types: string[] = [];
   123→    const startIdx = Math.max(0, this.stack.length - count);
   124→    for (let i = startIdx; i < this.stack.length; i++) {
   125→      types.push(this.inferType(this.stack[i]));
   126→    }
   127→    return types;
   128→  }
   129→
   130→  /**
   131→   * Phase 21: Check type compatibility and generate warnings
   132→   */
   133→  private checkTypeCompatibility(funcName: string, argTypes: string[], expectedParams: Record<string, string>, paramNames: string[]): boolean {
   134→    const result = this.typeChecker.checkFunctionCall(
   135→      funcName,
   136→      argTypes,
   137→      expectedParams,
   138→      paramNames
   139→    );
   140→
   141→    if (!result.compatible) {
   142→      this.typeWarnings.push({
   143→        functionName: funcName,
   144→        message: result.message,
   145→        timestamp: new Date(),
   146→        paramName: result.details?.paramName,
   147→        expectedType: result.details?.expected,
   148→        receivedType: result.details?.received
   149→      });
   150→      console.warn(`Type warning in '${funcName}': ${result.message}`);
   151→    }
   152→
   153→    return result.compatible;
   154→  }
   155→
   156→  /**
   157→   * Phase 21: Get type warnings
   158→   */
   159→  getTypeWarnings(): TypeWarning[] {
   160→    return [...this.typeWarnings];
   161→  }
   162→
   163→  /**
   164→   * Phase 21: Clear type warnings
   165→   */
   166→  clearTypeWarnings(): void {
   167→    this.typeWarnings = [];
   168→  }
   169→
   170→  /**
   171→   * Phase 21: Get warning count
   172→   */
   173→  getWarningCount(): number {
   174→    return this.typeWarnings.length;
   175→  }
   176→
   177→  run(program: Inst[]): VMResult {
   178→    this.stack = [];
   179→    this.vars = new Map();
   180→    this.pc = 0;
   181→    this.cycles = 0;
   182→    this.callStack = [];
   183→    this.tryStack = [];  // Phase I: Reset exception stack
   184→    const t0 = performance.now();
   185→
   186→    try {
   187→      // Performance optimization: hot path execution
   188→      while (this.pc < program.length) {
   189→        if (this.cycles++ > MAX_CYCLES) {
   190→          return this.fail(program[this.pc]?.op ?? Op.HALT, 1, 'cycle_limit');
   191→        }
   192→        const inst = program[this.pc];
   193→
   194→        // Hot path: handle most common operations directly
   195→        if (this.hotPathOps.has(inst.op)) {
   196→          this.execHotPath(inst, program);
   197→        } else {
   198→          this.exec(inst, program);
   199→        }
   200→
   201→        if (inst.op === Op.HALT) break;
   202→      }
   203→
   204→      const value = this.stack.length > 0 ? this.stack[this.stack.length - 1] : undefined;
   205→      return { ok: true, value, cycles: this.cycles, ms: performance.now() - t0 };
   206→    } catch (e: unknown) {
   207→      const msg = e instanceof Error ? e.message : String(e);
   208→      return this.fail(program[this.pc]?.op ?? Op.HALT, 99, msg, performance.now() - t0);
   209→    }
   210→  }
   211→
   212→  /**
   213→   * Hot path execution for most common operations
   214→   * Performance optimization (Phase C): Avoid switch dispatch overhead
   215→   */
   216→  private execHotPath(inst: Inst, program: Inst[]): void {
   217→    const op = inst.op;
   218→
   219→    // PUSH: most common operation
   220→    if (op === Op.PUSH) {
   221→      this.guardStack();
   222→      this.stack.push(inst.arg as number);
   223→      this.pc++;
   224→      return;
   225→    }
   226→
   227→    // POP
   228→    if (op === Op.POP) {
   229→      this.need(1);
   230→      this.stack.pop();
   231→      this.pc++;
   232→      return;
   233→    }
   234→
   235→    // Binary arithmetic (hot operations in math-heavy code)
   236→    if (op === Op.ADD) {
   237→      this.binop((a, b) => a + b);
   238→      return;
   239→    }
   240→    if (op === Op.SUB) {
   241→      this.binop((a, b) => a - b);
   242→      return;
   243→    }
   244→    if (op === Op.MUL) {
   245→      this.binop((a, b) => a * b);
   246→      return;
   247→    }
   248→    if (op === Op.DIV) {
   249→      this.need(2);
   250→      if (this.stack[this.stack.length - 1] === 0) {
   251→        throw new Error('div_zero');
   252→      }
   253→      this.binop((a, b) => a / b);
   254→      return;
   255→    }
   256→
   257→    // LOAD: common variable access
   258→    if (op === Op.LOAD) {
   259→      const varName = inst.arg as string;
   260→      const v = this.vars.get(varName);
   261→      if (process.env.DEBUG_STORE) {
   262→        console.log(`[DEBUG LOAD] Getting vars["${varName}"]`);
   263→        console.log(`[DEBUG LOAD] vars keys available:`, Array.from(this.vars.keys()));
   264→        console.log(`[DEBUG LOAD] Result:`, v);
   265→      }
   266→      if (v === undefined) throw new Error('undef_var:' + varName);
   267→      this.guardStack();
   268→      this.stack.push(v);
   269→      this.pc++;
   270→      return;
   271→    }
   272→
   273→    // STORE: common variable assignment
   274→    if (op === Op.STORE) {
   275→      this.need(1);
   276→      const varName = inst.arg as string;
   277→      const value = this.stack.pop()!;
   278→      if (process.env.DEBUG_STORE) {
   279→        console.log(`[DEBUG STORE] Setting vars["${varName}"] = ${JSON.stringify(value)}`);
   280→        console.log(`[DEBUG STORE] vars keys before:`, Array.from(this.vars.keys()));
   281→      }
   282→      this.vars.set(varName, value);
   283→      if (process.env.DEBUG_STORE) {
   284→        console.log(`[DEBUG STORE] vars keys after:`, Array.from(this.vars.keys()));
   285→        console.log(`[DEBUG STORE] vars["${varName}"] =`, this.vars.get(varName));
   286→      }
   287→      this.pc++;
   288→      return;
   289→    }
   290→
   291→    // Fallback to main exec for other hot path ops
   292→    this.exec(inst, program);
   293→  }
   294→
   295→  private exec(inst: Inst, program: Inst[]): void {
   296→    const { op, arg } = inst;
   297→
   298→    switch (op) {
   299→      // ── Stack ──
   300→      case Op.PUSH:
   301→        this.guardStack();
   302→        this.stack.push(arg as number);
   303→        this.pc++;
   304→        break;
   305→
   306→      case Op.PUSH_FLOAT:
   307→        this.guardStack();
   308→        this.stack.push(arg as number);  // JavaScript number is 64-bit float
   309→        this.pc++;
   310→        break;
   311→
   312→      case Op.POP:
   313→        this.need(1);
   314→        this.stack.pop();
   315→        this.pc++;
   316→        break;
   317→
   318→      case Op.DUP:
   319→        this.need(1);
   320→        this.guardStack();
   321→        this.stack.push(this.stack[this.stack.length - 1]);
   322→        this.pc++;
   323→        break;
   324→
   325→      // ── Arithmetic ──
   326→      case Op.ADD: this.binop((a, b) => a + b); break;
   327→      case Op.SUB: this.binop((a, b) => a - b); break;
   328→      case Op.MUL: this.binop((a, b) => a * b); break;
   329→      case Op.DIV:
   330→        this.need(2);
   331→        if (this.stack[this.stack.length - 1] === 0) {
   332→          throw new Error('div_zero');
   333→        }
   334→        this.binop((a, b) => a / b);
   335→        break;
   336→      case Op.MOD: this.binop((a, b) => a % b); break;
   337→      case Op.NEG:
   338→        this.need(1);
   339→        this.stack[this.stack.length - 1] = -this.stack[this.stack.length - 1];
   340→        this.pc++;
   341→        break;
   342→
   343→      // ── Float Arithmetic (Phase 3 Level 3) ──
   344→      case Op.FADD: this.binop((a, b) => a + b); break;  // Same as ADD (JavaScript number is f64)
   345→      case Op.FSUB: this.binop((a, b) => a - b); break;
   346→      case Op.FMUL: this.binop((a, b) => a * b); break;
   347→      case Op.FDIV:
   348→        this.need(2);
   349→        if (this.stack[this.stack.length - 1] === 0) {
   350→          throw new Error('fdiv_zero');
   351→        }
   352→        this.binop((a, b) => a / b);
   353→        break;
   354→
   355→      // ── Float Conversions ──
   356→      case Op.F2I:  // float → int
   357→        this.need(1);
   358→        this.stack[this.stack.length - 1] = Math.trunc(this.stack[this.stack.length - 1] as number);
   359→        this.pc++;
   360→        break;
   361→      case Op.I2F:  // int → float (no-op in JavaScript, but semantically correct)
   362→        this.need(1);
   363→        this.stack[this.stack.length - 1] = Number(this.stack[this.stack.length - 1] as number);
   364→        this.pc++;
   365→        break;
   366→
   367→      // ── Comparison ──
   368→      case Op.EQ:  this.binop((a, b) => a === b ? 1 : 0); break;
   369→      case Op.NEQ: this.binop((a, b) => a !== b ? 1 : 0); break;
   370→      case Op.LT:  this.binop((a, b) => a < b ? 1 : 0); break;
   371→      case Op.GT:  this.binop((a, b) => a > b ? 1 : 0); break;
   372→      case Op.LTE: this.binop((a, b) => a <= b ? 1 : 0); break;
   373→      case Op.GTE: this.binop((a, b) => a >= b ? 1 : 0); break;
   374→
   375→      // ── Logic ──
   376→      case Op.AND: this.binop((a, b) => (a && b) ? 1 : 0); break;
   377→      case Op.OR:  this.binop((a, b) => (a || b) ? 1 : 0); break;
   378→      case Op.NOT:
   379→        this.need(1);
   380→        this.stack[this.stack.length - 1] = this.stack[this.stack.length - 1] ? 0 : 1;
   381→        this.pc++;
   382→        break;
   383→
   384→      // ── Variables ──
   385→      case Op.STORE:
   386→        this.need(1);
   387→        this.vars.set(arg as string, this.stack.pop()!);
   388→        this.pc++;
   389→        break;
   390→
   391→      case Op.LOAD: {
   392→        const v = this.vars.get(arg as string);
   393→        if (v === undefined) throw new Error('undef_var:' + arg);
   394→        // Push any value type to stack (number, string, array, object)
   395→        this.guardStack();
   396→        this.stack.push(v);
   397→        this.pc++;
   398→        break;
   399→      }
   400→
   401→      // ── Control ──
   402→      case Op.JMP:
   403→        this.pc = arg as number;
   404→        break;
   405→
   406→      case Op.JMP_IF:
   407→        this.need(1);
   408→        this.pc = this.stack.pop()! ? (arg as number) : this.pc + 1;
   409→        break;
   410→
   411→      case Op.JMP_NOT:
   412→        this.need(1);
   413→        this.pc = this.stack.pop()! ? this.pc + 1 : (arg as number);
   414→        break;
   415→
   416→      case Op.RET:
   417→      case Op.HALT:
   418→        this.pc = program.length; // exit
   419→        break;
   420→
   421→      // ── Array ──
   422→      case Op.ARR_NEW:
   423→        this.vars.set(arg as string, []);
   424→        this.pc++;
   425→        break;
   426→
   427→      case Op.ARR_PUSH: {
   428→        this.need(1);
   429→        const arr = this.vars.get(arg as string);
   430→        if (!Array.isArray(arr)) throw new Error('not_array:' + arg);
   431→        arr.push(this.stack.pop() as number);
   432→        this.pc++;
   433→        break;
   434→      }
   435→
   436→      case Op.ARR_GET: {
   437→        this.need(2);
   438→        // If arg is provided, use variable-based access
   439→        // Otherwise use stack-based access: stack = [... array/object, index/key]
   440→        let container;
   441→        let key;
   442→
   443→        if (arg) {
   444→          // Variable-based: container = vars[arg], key = stack.pop()
   445→          container = this.vars.get(arg as string);
   446→          if (!container || (typeof container !== 'object')) throw new Error('not_indexable:' + arg);
   447→          key = this.stack.pop();
   448→        } else {
   449→          // Stack-based: pop key, then pop container (array or object)
   450→          key = this.stack.pop();
   451→          container = this.stack.pop();
   452→          if (!container || typeof container !== 'object') throw new Error('not_indexable:stack');
   453→        }
   454→
   455→        // Handle both arrays and objects
   456→        let value;
   457→        if (Array.isArray(container)) {
   458→          // Convert float indices to int (truncate)
   459→          const idx = Math.floor(key as number);
   460→          if (idx < 0 || idx >= container.length) throw new Error('oob:' + idx);
   461→          value = container[idx];
   462→        } else {
   463→          // Object: use string key
   464→          const strKey = String(key);
   465→          value = (container as any)[strKey];
   466→        }
   467→
   468→        this.guardStack();
   469→        this.stack.push(value);
   470→        this.pc++;
   471→        break;
   472→      }
   473→
   474→      case Op.ARR_SET: {
   475→        this.need(2);
   476→        const container = this.vars.get(arg as string);
   477→        if (!container || typeof container !== 'object') throw new Error('not_indexable:' + arg);
   478→        const val = this.stack.pop();
   479→        const key = this.stack.pop();
   480→
   481→        // Handle both arrays and objects
   482→        if (Array.isArray(container)) {
   483→          // Convert float indices to int (truncate)
   484→          const idx = Math.floor(key as number);
   485→          if (idx < 0 || idx >= container.length) throw new Error('oob:' + idx);
   486→          container[idx] = val;
   487→        } else {
   488→          // Object: use string key
   489→          const strKey = String(key);
   490→          (container as any)[strKey] = val;
   491→        }
   492→
   493→        this.pc++;
   494→        break;
   495→      }
   496→
   497→      case Op.ARR_LEN: {
   498→        let value;
