  1387→  private binop(fn: (a: number, b: number) => number): void {
  1388→    this.need(2);
  1389→    const b = this.stack.pop() as number;
  1390→    const a = this.stack.pop() as number;
  1391→    this.guardStack();
  1392→    this.stack.push(fn(a, b));
  1393→    this.pc++;
  1394→  }
