  1396→  private need(n: number): void {
  1397→    if (this.stack.length < n) {
  1398→      throw new Error('stack_underflow:need=' + n + ',have=' + this.stack.length);
  1399→    }
  1400→  }
  1401→
  1402→  private guardStack(): void {
  1403→    if (this.stack.length >= MAX_STACK) {
  1404→      throw new Error('stack_overflow');
  1405→    }
  1406→  }
