  1414→  private runSub(subProgram: Inst[]): VMResult {
  1415→    const savedPc = this.pc;
  1416→    this.pc = 0;
  1417→    while (this.pc < subProgram.length) {
  1418→      if (this.cycles++ > 100_000) {
  1419→        const result = this.fail(Op.HALT, 1, 'cycle_limit');
  1420→        this.pc = savedPc;
  1421→        return result;
  1422→      }
  1423→      const inst = subProgram[this.pc];
  1424→      if (inst.op === Op.RET || inst.op === Op.HALT) {
  1425→        this.pc = savedPc;
  1426→        break;
  1427→      }
  1428→      this.exec(inst, subProgram);
  1429→    }
  1430→    this.pc = savedPc;
  1431→    return { ok: true, value: undefined, cycles: this.cycles, ms: 0 };
  1432→  }
