  1434→  /**
  1435→   * Phase 19: Run a program IR and return its result
  1436→   * Used for function body execution
  1437→   */
  1438→  private runProgram(program: Inst[]): VMResult {
  1439→    const savedPc = this.pc;
  1440→    const savedStack = this.stack;  // Save reference, not copy
  1441→    this.stack = [];  // Isolated stack for this sub-program
  1442→    this.pc = 0;
  1443→
  1444→    try {
  1445→      while (this.pc < program.length) {
  1446→        if (this.cycles++ > 100_000) {
  1447→          this.pc = savedPc;
  1448→          this.stack = savedStack;  // Restore stack before returning
  1449→          return this.fail(Op.HALT, 1, 'cycle_limit');
  1450→        }
  1451→        const inst = program[this.pc];
  1452→        if (inst.op === Op.RET || inst.op === Op.HALT) {
  1453→          break;
  1454→        }
  1455→        this.exec(inst, program);
  1456→      }
  1457→
  1458→      // Get return value from stack
  1459→      const value = this.stack.length > 0 ? this.stack[this.stack.length - 1] : undefined;
  1460→      this.pc = savedPc;
  1461→      this.stack = savedStack;  // Restore stack before returning (was missing in success path!)
  1462→      return { ok: true, value, cycles: this.cycles, ms: 0 };
  1463→    } catch (e: unknown) {
  1464→      this.pc = savedPc;
  1465→      this.stack = savedStack;  // Restore stack on error
  1466→      const msg = e instanceof Error ? e.message : String(e);
  1467→      return this.fail(Op.HALT, 99, msg);
  1468→    }
  1469→  }
