  1471→  /**
  1472→   * Phase 26: Execute user-defined function with arguments (for higher-order functions)
  1473→   * Used by map/filter/reduce callbacks
  1474→   */
  1475→  public callUserFunction(functionName: string, args: any[]): any {
  1476→    if (!this.functionRegistry || !this.functionRegistry.exists(functionName)) {
  1477→      throw new Error(`Function not found: ${functionName}`);
  1478→    }
  1479→
  1480→    const fn = this.functionRegistry.lookup(functionName);
  1481→    if (!fn) throw new Error('function_lookup_failed:' + functionName);
  1482→
  1483→    // Save current state
  1484→    const savedVars = this.vars;
  1485→    this.vars = new Map(savedVars);
  1486→
  1487→    // Bind parameters
  1488→    for (let i = 0; i < fn.params.length; i++) {
  1489→      this.vars.set(fn.params[i], args[i]);
  1490→    }
  1491→
  1492→    // Execute function body
  1493→    const gen = new IRGenerator();
  1494→    const bodyNode = fn.body || { type: 'block', body: [] };
  1495→    const bodyIR = gen.generateIR(bodyNode);
  1496→
  1497→    let returnValue: any = undefined;
  1498→    const result = this.runProgram(bodyIR);
  1499→    returnValue = result.value;
  1500→
  1501→    // Restore caller's variables
  1502→    this.vars = savedVars;
  1503→
  1504→    return returnValue;
  1505→  }
