  1507→  /**
  1508→   * Phase 7-D: Execute closure (lambda/anonymous function) with arguments
  1509→   * Closures can be passed as function values to higher-order functions like map/filter/reduce
  1510→   */
  1511→  public callClosure(closure: any, args: any[]): any {
  1512→    // Validate closure structure
  1513→    if (!closure || closure.type !== 'lambda') {
  1514→      throw new Error('invalid_closure:expected_lambda_object');
  1515→    }
  1516→
  1517→    // Save current state and create new scope
  1518→    const savedVars = this.vars;
  1519→    this.vars = new Map(savedVars);
  1520→
  1521→    // If closure has captured variables, restore them (B4 수정: string[] 처리)
  1522→    if (closure.capturedVars && Array.isArray(closure.capturedVars)) {
  1523→      for (const varName of closure.capturedVars) {
  1524→        // varName은 string이므로 직접 사용
  1525→        const name = typeof varName === 'string' ? varName : (varName as any).name;
  1526→        if (name && savedVars.has(name)) {
  1527→          this.vars.set(name, savedVars.get(name));
  1528→        }
  1529→      }
  1530→    }
  1531→
  1532→    // Bind closure parameters
  1533→    const paramNames = closure.params || [];
  1534→    for (let i = 0; i < paramNames.length && i < args.length; i++) {
  1535→      const paramName = typeof paramNames[i] === 'string' ? paramNames[i] : paramNames[i].name;
  1536→      this.vars.set(paramName, args[i]);
  1537→    }
  1538→
  1539→    // Execute closure body
  1540→    const gen = new IRGenerator();
  1541→    const bodyNode = closure.body;
  1542→    if (!bodyNode) {
  1543→      throw new Error('closure_body_undefined');
  1544→    }
  1545→
  1546→    const bodyIR = gen.generateIR(bodyNode);
  1547→    let returnValue: any = undefined;
  1548→
  1549→    try {
  1550→      const result = this.runProgram(bodyIR);
  1551→      returnValue = result.value;
  1552→    } catch (e) {
  1553→      // Restore variables before throwing
  1554→      this.vars = savedVars;
  1555→      throw e;
  1556→    }
  1557→
  1558→    // Restore caller's variables
  1559→    this.vars = savedVars;
  1560→
  1561→    return returnValue;
  1562→  }
  1563→
  1564→  /**
  1565→   * Get native function registry (for registering callbacks)
  1566→   */
  1567→  public getNativeFunctionRegistry(): NativeFunctionRegistry {
  1568→    return this.nativeFunctionRegistry;
  1569→  }
  1570→
  1571→  private fail(op: Op, code: number, detail: string, ms?: number): VMResult {
  1572→    return {
  1573→      ok: false,
  1574→      cycles: this.cycles,
  1575→      ms: ms ?? 0,
  1576→      error: {
  1577→        code,
  1578→        op,
  1579→        pc: this.pc,
  1580→        stack_depth: this.stack.length,
  1581→        detail,
  1582→      },
  1583→    };
  1584→  }
  1585→
  1586→  // ── Callback Management (Phase 16-17) ──
  1587→  registerCallback(bytecode: Inst[]): number {
  1588→    const id = this.nextCallbackId++;
  1589→    this.callbackRegistry.set(id, bytecode);
  1590→    return id;
  1591→  }
  1592→
  1593→  executeCallback(callbackId: number, _args?: any[]): VMResult {
  1594→    const bytecode = this.callbackRegistry.get(callbackId);
  1595→    if (!bytecode) {
  1596→      return this.fail(Op.HALT, 1, `callback_not_found:${callbackId}`);
  1597→    }
  1598→
  1599→    // Execute callback bytecode in isolated context
  1600→    const savedStack = this.stack;
  1601→    const savedVars = this.vars;
  1602→    const savedPc = this.pc;
  1603→
  1604→    this.stack = [];
  1605→    this.vars = new Map();
  1606→    this.pc = 0;
  1607→
  1608→    const result = this.run(bytecode);
  1609→
  1610→    this.stack = savedStack;
  1611→    this.vars = savedVars;
  1612→    this.pc = savedPc;
  1613→
  1614→    return result;
  1615→  }
  1616→
  1617→  /**
  1618→   * Phase 3 FFI: Register a native (C FFI) function
  1619→   */
  1620→  registerNativeFunction(config: NativeFunctionConfig): boolean {
  1621→    return this.nativeFunctionRegistry.register(config);
  1622→  }
  1623→
  1624→  /**
  1625→   * Phase 3 FFI: Get statistics about registered native functions
  1626→   */
  1627→  getNativeFunctionStats(): { totalFunctions: number; modules: Record<string, number> } {
  1628→    return this.nativeFunctionRegistry.getStats();
  1629→  }
  1630→
  1631→  /**
  1632→   * Phase 3 FFI: Check if a native function exists
  1633→   */
  1634→  hasNativeFunction(name: string): boolean {
  1635→    return this.nativeFunctionRegistry.exists(name);
  1636→  }
  1637→
  1638→  /**
  1639→   * Phase 3 FFI: List all available native functions
  1640→   */
  1641→  listNativeFunctions(): string[] {
  1642→    return this.nativeFunctionRegistry.listAll();
  1643→  }
  1644→
  1645→  // ── Phase 4: JIT Hotspot Detection ──
  1646→  /**
  1647→   * Get hotspot detection report
  1648→   */
  1649→  getHotspotReport(): string {
  1650→    return generateHotspotReport();
  1651→  }
  1652→
  1653→  /**
  1654→   * Check if a function is "hot" (called >= 100 times)
  1655→   */
  1656→  isHotFunction(funcName: string): boolean {
  1657→    return isHotFunction(funcName);
  1658→  }
  1659→
  1660→  // ── State inspection (for AI) ──
  1661→  getStack(): readonly unknown[] { return this.stack; }
  1662→  getVar(name: string): unknown { return this.vars.get(name); }
