     1→// FreeLang v4 — Stack VM (SPEC_02 구현)
     2→// fetch-decode-execute + Actor cooperative scheduling
     3→// Phase 1 수정: GC 통합
     4→
     5→import { Op, Chunk, FuncInfo } from "./compiler";
     6→import { GCEngine, GCStats } from "../gc/gc-engine";
     7→import * as crypto from "crypto";
     8→
     9→// ============================================================
    10→// Value (SPEC_02 Q3)
    11→// ============================================================
    12→
    13→export type Value =
    14→  | { tag: "i32"; val: number }
    15→  | { tag: "f64"; val: number }
    16→  | { tag: "str"; val: string }
    17→  | { tag: "bool"; val: boolean }
    18→  | { tag: "arr"; val: Value[] }
    19→  | { tag: "struct"; fields: Map<string, Value> }
    20→  | { tag: "ok"; val: Value }
    21→  | { tag: "err"; val: Value }
    22→  | { tag: "some"; val: Value }
    23→  | { tag: "none" }
    24→  | { tag: "chan"; id: number }
    25→  | { tag: "void" };
    26→
    27→// ============================================================
    28→// CallFrame (SPEC_02 Q5)
    29→// ============================================================
    30→
    31→type CallFrame = {
    32→  returnAddr: number;
    33→  baseSlot: number;
    34→  locals: Value[];
    35→};
    36→
    37→// ============================================================
    38→// Channel
    39→// ============================================================
    40→
    41→type Channel = {
    42→  id: number;
    43→  buffer: Value[];
    44→  waitingRecv: number[]; // actor ids waiting to recv
    45→};
    46→
    47→// ============================================================
    48→// Actor (SPEC_02 Q7)
    49→// ============================================================
    50→
    51→type Actor = {
    52→  id: number;
    53→  ip: number;
    54→  stack: Value[];
    55→  frames: CallFrame[];
    56→  state: "running" | "waiting" | "done";
    57→  waitingChan: number | null;
    58→};
    59→
    60→// ============================================================
    61→// VM
    62→// ============================================================
    63→
    64→export class VM {
    65→  private chunk!: Chunk;
    66→  private actors: Actor[] = [];
    67→  private channels: Channel[] = [];
    68→  private globals: Map<string, Value> = new Map();
    69→  private output: string[] = [];
    70→  private instructionCount: number = 0;
    71→  private maxInstructions: number = 1_000_000;
    72→
    73→  // Phase 1 추가: GC 엔진
    74→  private gc: GCEngine = new GCEngine();
    75→  private gcStats: GCStats[] = [];
    76→  private callCount: number = 0; // GC 트리거 카운터
    77→
    78→  run(chunk: Chunk): { output: string[]; error: string | null } {
    79→    this.chunk = chunk;
    80→    this.output = [];
    81→    this.instructionCount = 0;
    82→
    83→    // main actor
    84→    this.actors = [{
    85→      id: 0,
    86→      ip: 0,
    87→      stack: [],
    88→      frames: [{ returnAddr: -1, baseSlot: 0, locals: [] }],
    89→      state: "running",
    90→      waitingChan: null,
    91→    }];
    92→
    93→    try {
    94→      this.schedule();
    95→      return { output: this.output, error: null };
    96→    } catch (e: any) {
    97→      return { output: this.output, error: e.message || String(e) };
    98→    }
    99→  }
   100→
   101→  // ============================================================
   102→  // Scheduler — round-robin (SPEC_02 Q7)
   103→  // ============================================================
   104→
   105→  private schedule(): void {
   106→    const SLICE = 1000;
   107→    let current = 0;
   108→
   109→    while (this.actors.some((a) => a.state !== "done")) {
   110→      const actor = this.actors[current];
   111→
   112→      if (actor.state === "running") {
   113→        this.runSlice(actor, SLICE);
   114→      } else if (actor.state === "waiting" && actor.waitingChan !== null) {
   115→        const chan = this.channels.find((c) => c.id === actor.waitingChan);
   116→        if (chan && chan.buffer.length > 0) {
   117→          const val = chan.buffer.shift()!;
   118→          actor.stack.push({ tag: "ok", val });
   119→          actor.state = "running";
   120→          actor.waitingChan = null;
   121→        }
   122→      }
   123→
   124→      current = (current + 1) % this.actors.length;
   125→
   126→      if (this.instructionCount > this.maxInstructions) {
   127→        throw new Error("execution limit exceeded (infinite loop?)");
   128→      }
   129→    }
   130→  }
   131→
   132→  // ============================================================
   133→  // Execute slice
   134→  // ============================================================
   135→
   136→  private runSlice(actor: Actor, maxOps: number): void {
   137→    let ops = 0;
   138→
   139→    while (ops < maxOps && actor.state === "running") {
   140→      if (actor.ip >= this.chunk.code.length) {
   141→        actor.state = "done";
   142→        return;
   143→      }
   144→
   145→      const op = this.chunk.code[actor.ip++];
   146→      this.instructionCount++;
   147→      ops++;
   148→
   149→      switch (op) {
   150→        // ---- 상수 로드 ----
   151→        case Op.PUSH_I32: {
   152→          const val = this.readI32(actor);
   153→          actor.stack.push({ tag: "i32", val });
   154→          break;
   155→        }
   156→        case Op.PUSH_F64: {
   157→          const val = this.readF64(actor);
   158→          actor.stack.push({ tag: "f64", val });
   159→          break;
   160→        }
   161→        case Op.PUSH_STR: {
   162→          const idx = this.readI32(actor);
   163→          actor.stack.push({ tag: "str", val: this.chunk.constants[idx] });
   164→          break;
   165→        }
   166→        case Op.PUSH_TRUE:
   167→          actor.stack.push({ tag: "bool", val: true });
   168→          break;
   169→        case Op.PUSH_FALSE:
   170→          actor.stack.push({ tag: "bool", val: false });
   171→          break;
   172→        case Op.PUSH_VOID:
   173→          actor.stack.push({ tag: "void" });
   174→          break;
   175→        case Op.PUSH_NONE:
   176→          actor.stack.push({ tag: "none" });
   177→          break;
   178→        case Op.POP:
   179→          actor.stack.pop();
   180→          break;
   181→        case Op.DUP:
   182→          actor.stack.push(actor.stack[actor.stack.length - 1]);
   183→          break;
   184→
   185→        // ---- 산술 (i32) ----
   186→        case Op.ADD_I32: {
   187→          const b = actor.stack.pop()!;
   188→          const a = actor.stack.pop()!;
   189→          if (a.tag === "str" && b.tag === "str") {
   190→            actor.stack.push({ tag: "str", val: a.val + b.val });
   191→          } else {
   192→            actor.stack.push({ tag: a.tag as any, val: (a as any).val + (b as any).val });
   193→          }
   194→          break;
   195→        }
   196→        case Op.SUB_I32: {
   197→          const b = actor.stack.pop()!;
   198→          const a = actor.stack.pop()!;
   199→          actor.stack.push({ tag: a.tag as any, val: (a as any).val - (b as any).val });
   200→          break;
   201→        }
   202→        case Op.MUL_I32: {
   203→          const b = actor.stack.pop()!;
   204→          const a = actor.stack.pop()!;
   205→          actor.stack.push({ tag: a.tag as any, val: (a as any).val * (b as any).val });
   206→          break;
   207→        }
   208→        case Op.DIV_I32: {
   209→          const b = actor.stack.pop()!;
   210→          const a = actor.stack.pop()!;
   211→          if ((b as any).val === 0) throw new Error("panic: division by zero");
   212→          const result = a.tag === "i32"
   213→            ? Math.trunc((a as any).val / (b as any).val)
   214→            : (a as any).val / (b as any).val;
   215→          actor.stack.push({ tag: a.tag as any, val: result });
   216→          break;
   217→        }
   218→        case Op.MOD_I32: {
   219→          const b = actor.stack.pop()!;
   220→          const a = actor.stack.pop()!;
   221→          if ((b as any).val === 0) throw new Error("panic: division by zero");
   222→          actor.stack.push({ tag: a.tag as any, val: (a as any).val % (b as any).val });
   223→          break;
   224→        }
   225→        case Op.NEG_I32: {
   226→          const a = actor.stack.pop()!;
   227→          actor.stack.push({ tag: a.tag as any, val: -(a as any).val });
   228→          break;
   229→        }
   230→
   231→        // ---- f64 산술 ----
   232→        case Op.ADD_F64: {
   233→          const b = actor.stack.pop()!;
   234→          const a = actor.stack.pop()!;
   235→          actor.stack.push({ tag: "f64", val: (a as any).val + (b as any).val });
   236→          break;
   237→        }
   238→        case Op.SUB_F64: {
   239→          const b = actor.stack.pop()!;
   240→          const a = actor.stack.pop()!;
   241→          actor.stack.push({ tag: "f64", val: (a as any).val - (b as any).val });
   242→          break;
   243→        }
   244→        case Op.MUL_F64: {
   245→          const b = actor.stack.pop()!;
   246→          const a = actor.stack.pop()!;
   247→          actor.stack.push({ tag: "f64", val: (a as any).val * (b as any).val });
   248→          break;
   249→        }
   250→        case Op.DIV_F64: {
   251→          const b = actor.stack.pop()!;
   252→          const a = actor.stack.pop()!;
   253→          const bval = (b as any).val;
   254→          actor.stack.push({ tag: "f64", val: bval === 0 ? Infinity : (a as any).val / bval });
   255→          break;
   256→        }
   257→        case Op.MOD_F64: {
   258→          const b = actor.stack.pop()!;
   259→          const a = actor.stack.pop()!;
   260→          const bval = (b as any).val;
   261→          if (bval === 0) throw new Error("panic: division by zero");
   262→          actor.stack.push({ tag: "f64", val: (a as any).val % bval });
   263→          break;
   264→        }
   265→        case Op.NEG_F64: {
   266→          const a = actor.stack.pop()!;
   267→          actor.stack.push({ tag: "f64", val: -(a as any).val });
   268→          break;
   269→        }
   270→
   271→        // ---- 비교 ----
   272→        case Op.EQ: {
   273→          const b = actor.stack.pop()!;
   274→          const a = actor.stack.pop()!;
   275→          actor.stack.push({ tag: "bool", val: this.valuesEqual(a, b) });
   276→          break;
   277→        }
   278→        case Op.NEQ: {
   279→          const b = actor.stack.pop()!;
   280→          const a = actor.stack.pop()!;
   281→          actor.stack.push({ tag: "bool", val: !this.valuesEqual(a, b) });
   282→          break;
   283→        }
   284→        case Op.LT: {
   285→          const b = actor.stack.pop()!;
   286→          const a = actor.stack.pop()!;
   287→          actor.stack.push({ tag: "bool", val: (a as any).val < (b as any).val });
   288→          break;
   289→        }
   290→        case Op.GT: {
   291→          const b = actor.stack.pop()!;
   292→          const a = actor.stack.pop()!;
   293→          actor.stack.push({ tag: "bool", val: (a as any).val > (b as any).val });
   294→          break;
   295→        }
   296→        case Op.LTEQ: {
   297→          const b = actor.stack.pop()!;
   298→          const a = actor.stack.pop()!;
   299→          actor.stack.push({ tag: "bool", val: (a as any).val <= (b as any).val });
   300→          break;
   301→        }
   302→        case Op.GTEQ: {
   303→          const b = actor.stack.pop()!;
   304→          const a = actor.stack.pop()!;
   305→          actor.stack.push({ tag: "bool", val: (a as any).val >= (b as any).val });
   306→          break;
   307→        }
   308→
   309→        // ---- 논리 ----
   310→        case Op.AND: {
   311→          const b = actor.stack.pop()!;
   312→          const a = actor.stack.pop()!;
   313→          actor.stack.push({ tag: "bool", val: (a as any).val && (b as any).val });
   314→          break;
   315→        }
   316→        case Op.OR: {
   317→          const b = actor.stack.pop()!;
   318→          const a = actor.stack.pop()!;
   319→          actor.stack.push({ tag: "bool", val: (a as any).val || (b as any).val });
   320→          break;
   321→        }
   322→        case Op.NOT: {
   323→          const a = actor.stack.pop()!;
   324→          actor.stack.push({ tag: "bool", val: !(a as any).val });
   325→          break;
   326→        }
   327→
   328→        // ---- 변수 ----
   329→        case Op.LOAD_LOCAL: {
   330→          const slot = this.readI32(actor);
   331→          const frame = actor.frames[actor.frames.length - 1];
   332→          actor.stack.push(frame.locals[slot] ?? { tag: "void" });
   333→          break;
   334→        }
   335→        case Op.STORE_LOCAL: {
   336→          const slot = this.readI32(actor);
   337→          const val = actor.stack.pop()!;
   338→          const frame = actor.frames[actor.frames.length - 1];
   339→          while (frame.locals.length <= slot) frame.locals.push({ tag: "void" });
   340→          frame.locals[slot] = val;
   341→          break;
   342→        }
   343→        case Op.LOAD_GLOBAL: {
   344→          const idx = this.readI32(actor);
   345→          const name = this.chunk.constants[idx];
   346→          actor.stack.push(this.globals.get(name) ?? { tag: "void" });
   347→          break;
   348→        }
   349→        case Op.STORE_GLOBAL: {
   350→          const idx = this.readI32(actor);
   351→          const name = this.chunk.constants[idx];
   352→          const val = actor.stack.pop()!;
   353→          this.globals.set(name, val);
   354→          break;
   355→        }
   356→
   357→        // ---- 제어 ----
   358→        case Op.JUMP: {
   359→          const target = this.readI32(actor);
   360→          actor.ip = target;
   361→          break;
   362→        }
   363→        case Op.JUMP_IF_FALSE: {
   364→          const target = this.readI32(actor);
   365→          const cond = actor.stack.pop()!;
   366→          if (cond.tag === "bool" && !cond.val) {
   367→            actor.ip = target;
   368→          }
   369→          break;
   370→        }
   371→        case Op.RETURN: {
   372→          const retVal = actor.stack.pop() ?? { tag: "void" as const };
   373→          const frame = actor.frames.pop()!;
   374→
   375→          if (actor.frames.length === 0) {
   376→            actor.state = "done";
   377→            return;
   378→          }
   379→
   380→          actor.ip = frame.returnAddr;
   381→          // 스택 정리
   382→          actor.stack.length = frame.baseSlot;
   383→          actor.stack.push(retVal);
   384→          break;
   385→        }
   386→        case Op.HALT:
   387→          // Phase 1: 프로그램 종료 전 최종 GC
   388→          const finalStat = this.gc.fullCollect();
   389→          this.gcStats.push(finalStat);
   390→
   391→          actor.state = "done";
   392→          return;
   393→
   394→        // ---- 함수 호출 ----
   395→        case Op.CALL: {
   396→          const fnIdx = this.readI32(actor);
   397→          const argCount = this.chunk.code[actor.ip++];
   398→
   399→          const fn = this.chunk.functions[fnIdx];
   400→          if (!fn) throw new Error(`panic: undefined function index ${fnIdx}`);
   401→
   402→          const args: Value[] = [];
   403→          for (let i = 0; i < argCount; i++) {
   404→            args.unshift(actor.stack.pop()!);
   405→          }
   406→
   407→          actor.frames.push({
   408→            returnAddr: actor.ip,
   409→            baseSlot: actor.stack.length,
   410→            locals: args,
   411→          });
   412→
   413→          actor.ip = fn.offset;
   414→
   415→          // Phase 1: GC 자동 실행 (1000회 함수 호출마다)
   416→          this.callCount++;
   417→          if (this.callCount >= 1000) {
   418→            const stat = this.gc.autoCollect();
   419→            this.gcStats.push(stat);
   420→            this.callCount = 0;
   421→          }
   422→          break;
   423→        }
   424→        case Op.CALL_BUILTIN: {
   425→          const nameIdx = this.readI32(actor);
   426→          const argCount = this.chunk.code[actor.ip++];
   427→          const name = this.chunk.constants[nameIdx];
   428→
   429→          const args: Value[] = [];
   430→          for (let i = 0; i < argCount; i++) {
   431→            args.unshift(actor.stack.pop()!);
   432→          }
   433→
   434→          const result = this.callBuiltin(name, args);
   435→          actor.stack.push(result);
   436→          break;
   437→        }
   438→
   439→        // ---- 배열 ----
   440→        case Op.ARRAY_NEW: {
   441→          const count = this.readI32(actor);
   442→          const elements: Value[] = [];
   443→          for (let i = 0; i < count; i++) {
   444→            elements.unshift(actor.stack.pop()!);
   445→          }
   446→
   447→          // Phase 1: GC 메모리 할당
   448→          // 배열 크기 추정: 각 요소당 ~32바이트 (tag + val)
   449→          const arraySize = count * 32;
   450→          const gcId = this.gc.allocate(arraySize);
   451→
   452→          // 스택에 배열 전체를 root로 추가
   453→          this.gc.addRoot(gcId);
   454→
   455→          const arr: Value = { tag: "arr", val: elements };
   456→          // GC 메타데이터 추가 (실제 구현에서는 Value에 gcId를 추가할 수 있음)
   457→          (arr as any).__gcId = gcId;
   458→
   459→          actor.stack.push(arr);
   460→          break;
   461→        }
   462→        case Op.ARRAY_GET: {
   463→          const idx = actor.stack.pop()!;
   464→          const arr = actor.stack.pop()!;
   465→          if (arr.tag !== "arr") throw new Error("panic: not an array");
   466→          const i = (idx as any).val;
   467→          if (i < 0 || i >= arr.val.length) throw new Error(`panic: index out of bounds: ${i}`);
   468→          actor.stack.push(arr.val[i]);
   469→          break;
   470→        }
   471→        case Op.ARRAY_SET: {
   472→          const val = actor.stack.pop()!;
   473→          const idx = actor.stack.pop()!;
   474→          const arr = actor.stack.pop()!;
   475→          if (arr.tag !== "arr") throw new Error("panic: not an array");
   476→          arr.val[(idx as any).val] = val;
   477→          break;
   478→        }
   479→
   480→        // ---- 구조체 ----
   481→        case Op.STRUCT_NEW: {
   482→          const count = this.readI32(actor);
   483→          const fields = new Map<string, Value>();
   484→          for (let i = 0; i < count; i++) {
   485→            const val = actor.stack.pop()!;
   486→            const key = actor.stack.pop()!;
   487→            fields.set((key as any).val, val);
   488→          }
   489→
   490→          // Phase 1: GC 메모리 할당
   491→          // 구조체 크기 추정: 헤더(32바이트) + 각 필드당 ~32바이트
   492→          const structSize = 32 + count * 32;
   493→          const gcId = this.gc.allocate(structSize);
   494→
   495→          // 스택에 구조체를 root로 추가
   496→          this.gc.addRoot(gcId);
   497→
   498→          const struct: Value = { tag: "struct", fields };
   499→          // GC 메타데이터 추가
   500→          (struct as any).__gcId = gcId;
   501→
   502→          actor.stack.push(struct);
   503→          break;
   504→        }
   505→        case Op.STRUCT_GET: {
   506→          const nameIdx = this.readI32(actor);
   507→          const fieldName = this.chunk.constants[nameIdx];
   508→          const obj = actor.stack.pop()!;
   509→          if (obj.tag !== "struct") throw new Error("panic: not a struct");
   510→          actor.stack.push(obj.fields.get(fieldName) ?? { tag: "void" });
   511→          break;
   512→        }
   513→
   514→        case Op.STRUCT_SET: {
   515→          const nameIdx = this.readI32(actor);
   516→          const fieldName = this.chunk.constants[nameIdx];
   517→          const value = actor.stack.pop()!;
   518→          const obj = actor.stack.pop()!;
   519→          if (obj.tag !== "struct") throw new Error("panic: not a struct");
   520→          obj.fields.set(fieldName, value);
   521→          actor.stack.push(obj);
   522→          break;
   523→        }
   524→
   525→        // ---- Option/Result ----
   526→        case Op.WRAP_OK: {
   527→          const val = actor.stack.pop()!;
   528→          actor.stack.push({ tag: "ok", val });
   529→          break;
   530→        }
   531→        case Op.WRAP_ERR: {
   532→          const val = actor.stack.pop()!;
   533→          actor.stack.push({ tag: "err", val });
   534→          break;
   535→        }
   536→        case Op.WRAP_SOME: {
   537→          const val = actor.stack.pop()!;
   538→          actor.stack.push({ tag: "some", val });
   539→          break;
   540→        }
   541→        case Op.WRAP_NONE: {
   542→          actor.stack.push({ tag: "none" });
   543→          break;
   544→        }
   545→        case Op.UNWRAP: {
   546→          const val = actor.stack.pop()!;
   547→          if (val.tag === "ok" || val.tag === "some") {
   548→            actor.stack.push(val.val);
   549→          } else {
   550→            throw new Error(`panic: unwrap on ${val.tag}`);
   551→          }
   552→          break;
   553→        }
   554→        case Op.IS_OK: {
   555→          const val = actor.stack.pop()!;
   556→          actor.stack.push({ tag: "bool", val: val.tag === "ok" });
   557→          break;
   558→        }
   559→        case Op.IS_ERR: {
   560→          const val = actor.stack.pop()!;
   561→          actor.stack.push({ tag: "bool", val: val.tag === "err" });
   562→          break;
   563→        }
   564→        case Op.IS_SOME: {
   565→          const val = actor.stack.pop()!;
   566→          actor.stack.push({ tag: "bool", val: val.tag === "some" });
   567→          break;
   568→        }
   569→        case Op.IS_NONE: {
   570→          const val = actor.stack.pop()!;
   571→          actor.stack.push({ tag: "bool", val: val.tag === "none" });
   572→          break;
   573→        }
   574→
   575→        // ---- Actor/Channel ----
   576→        case Op.SPAWN: {
   577→          const bodyOffset = this.readI32(actor);
   578→          const newActor: Actor = {
   579→            id: this.actors.length,
   580→            ip: bodyOffset,
   581→            stack: [],
   582→            frames: [{ returnAddr: -1, baseSlot: 0, locals: [] }],
   583→            state: "running",
   584→            waitingChan: null,
   585→          };
   586→          this.actors.push(newActor);
   587→          break;
   588→        }
   589→        case Op.CHAN_NEW: {
   590→          const chan: Channel = {
   591→            id: this.channels.length,
   592→            buffer: [],
   593→            waitingRecv: [],
   594→          };
   595→          this.channels.push(chan);
   596→          actor.stack.push({ tag: "chan", id: chan.id });
   597→          break;
   598→        }
   599→        case Op.CHAN_SEND: {
   600→          const val = actor.stack.pop()!;
   601→          const chanVal = actor.stack.pop()!;
   602→          if (chanVal.tag !== "chan") throw new Error("panic: send on non-channel");
   603→          const chan = this.channels[chanVal.id];
   604→          chan.buffer.push(val);
   605→          // 대기 중인 actor 깨우기
   606→          if (chan.waitingRecv.length > 0) {
   607→            const waitId = chan.waitingRecv.shift()!;
   608→            const waitActor = this.actors[waitId];
   609→            if (waitActor) {
   610→              waitActor.state = "running";
   611→              waitActor.waitingChan = null;
   612→            }
   613→          }
   614→          break;
   615→        }
   616→        case Op.CHAN_RECV: {
   617→          const chanVal = actor.stack.pop()!;
   618→          if (chanVal.tag !== "chan") throw new Error("panic: recv on non-channel");
   619→          const chan = this.channels[chanVal.id];
   620→          if (chan.buffer.length > 0) {
   621→            const val = chan.buffer.shift()!;
   622→            actor.stack.push({ tag: "ok", val });
   623→          } else {
   624→            // 대기 상태로 전환
   625→            actor.state = "waiting";
   626→            actor.waitingChan = chanVal.id;
   627→            chan.waitingRecv.push(actor.id);
   628→            return;
   629→          }
   630→          break;
   631→        }
   632→
   633→        default:
   634→          throw new Error(`panic: unknown opcode 0x${op.toString(16)}`);
   635→      }
   636→    }
   637→  }
   638→
   639→  // ============================================================
   640→  // 내장 함수 (SPEC_10)
   641→  // ============================================================
   642→
   643→  private callBuiltin(name: string, args: Value[]): Value {
   644→    switch (name) {
   645→      case "println": {
   646→        const text = args.map((a) => this.valueToString(a)).join(" ");
   647→        this.output.push(text);
   648→        return { tag: "void" };
   649→      }
   650→      case "print": {
   651→        const text = args.map((a) => this.valueToString(a)).join(" ");
   652→        // print는 줄바꿈 없이 마지막 출력에 이어붙임
   653→        if (this.output.length > 0) {
   654→          this.output[this.output.length - 1] += text;
   655→        } else {
   656→          this.output.push(text);
   657→        }
   658→        return { tag: "void" };
   659→      }
   660→      case "str":
   661→        return { tag: "str", val: this.valueToString(args[0]) };
   662→      case "length":
   663→        if (args[0].tag === "arr") return { tag: "i32", val: args[0].val.length };
   664→        if (args[0].tag === "str") return { tag: "i32", val: args[0].val.length };
   665→        return { tag: "i32", val: 0 };
   666→      case "range": {
   667→        const start = (args[0] as any).val;
   668→        const end = (args[1] as any).val;
   669→        const arr: Value[] = [];
   670→        for (let i = start; i < end; i++) arr.push({ tag: "i32", val: i });
   671→        return { tag: "arr", val: arr };
   672→      }
   673→      case "push":
   674→        if (args[0].tag === "arr") args[0].val.push(args[1]);
   675→        return { tag: "void" };
   676→      case "pop":
   677→        if (args[0].tag === "arr") return args[0].val.pop() ?? { tag: "void" };
   678→        return { tag: "void" };
   679→      case "abs":
   680→        return { tag: (args[0] as any).tag, val: Math.abs((args[0] as any).val) };
   681→      case "min":
   682→        return { tag: (args[0] as any).tag, val: Math.min((args[0] as any).val, (args[1] as any).val) };
   683→      case "max":
   684→        return { tag: (args[0] as any).tag, val: Math.max((args[0] as any).val, (args[1] as any).val) };
   685→      case "pow":
   686→        return { tag: "f64", val: Math.pow((args[0] as any).val, (args[1] as any).val) };
   687→      case "sqrt":
   688→        return { tag: "f64", val: Math.sqrt((args[0] as any).val) };
   689→      case "typeof":
   690→        return { tag: "str", val: args[0].tag };
   691→      case "assert":
   692→        if (args[0].tag === "bool" && !args[0].val) {
   693→          const msg = args.length > 1 ? this.valueToString(args[1]) : "assertion failed";
   694→          throw new Error(`panic: ${msg}`);
   695→        }
   696→        return { tag: "void" };
   697→      case "panic":
   698→        throw new Error(`panic: ${this.valueToString(args[0])}`);
   699→      case "contains":
   700→        if (args[0].tag === "str") {
   701→          return { tag: "bool", val: args[0].val.includes((args[1] as any).val) };
   702→        }
   703→        return { tag: "bool", val: false };
   704→      case "split":
   705→        if (args[0].tag === "str") {
   706→          const parts = args[0].val.split((args[1] as any).val);
   707→          return { tag: "arr", val: parts.map((s) => ({ tag: "str" as const, val: s })) };
   708→        }
   709→        return { tag: "arr", val: [] };
   710→      case "trim":
   711→        if (args[0].tag === "str") return { tag: "str", val: args[0].val.trim() };
   712→        return args[0];
   713→      case "to_upper":
   714→        if (args[0].tag === "str") return { tag: "str", val: args[0].val.toUpperCase() };
   715→        return args[0];
   716→      case "to_lower":
   717→        if (args[0].tag === "str") return { tag: "str", val: args[0].val.toLowerCase() };
   718→        return args[0];
   719→      case "char_at":
   720→        if (args[0].tag === "str") {
   721→          const i = (args[1] as any).val;
   722→          return { tag: "str", val: args[0].val[i] ?? "" };
   723→        }
   724→        return { tag: "str", val: "" };
   725→      case "slice":
   726→        if (args[0].tag === "arr") {
   727→          const s = (args[1] as any).val;
   728→          const e = (args[2] as any).val;
   729→          return { tag: "arr", val: args[0].val.slice(s, e) };
   730→        }
   731→        if (args[0].tag === "str") {
   732→          const s = (args[1] as any).val;
   733→          const e = (args[2] as any).val;
   734→          return { tag: "str", val: args[0].val.slice(s, e) };
   735→        }
   736→        return args[0];
   737→      case "clone":
   738→        return this.deepClone(args[0]);
   739→      case "channel": {
   740→        const chan: Channel = { id: this.channels.length, buffer: [], waitingRecv: [] };
   741→        this.channels.push(chan);
   742→        return { tag: "chan", id: chan.id };
   743→      }
   744→      case "i32":
   745→        return { tag: "ok", val: { tag: "i32", val: parseInt(this.valueToString(args[0]), 10) || 0 } };
   746→      case "i64":
   747→        return { tag: "ok", val: { tag: "i32", val: parseInt(this.valueToString(args[0]), 10) || 0 } };
   748→      case "f64":
   749→        return { tag: "ok", val: { tag: "f64", val: parseFloat(this.valueToString(args[0])) || 0 } };
   750→      case "read_line":
   751→        return { tag: "str", val: "" }; // stub
   752→      case "read_file":
   753→        return { tag: "err", val: { tag: "str", val: "not implemented" } };
   754→      case "write_file":
   755→        return { tag: "err", val: { tag: "str", val: "not implemented" } };
   756→      case "recv":
   757→        // method-style: obj.recv()
   758→        if (args[0] && args[0].tag === "chan") {
   759→          const chan = this.channels[args[0].id];
   760→          if (chan && chan.buffer.length > 0) {
   761→            return { tag: "ok", val: chan.buffer.shift()! };
   762→          }
   763→          return { tag: "err", val: { tag: "str", val: "channel empty" } };
   764→        }
   765→        return { tag: "err", val: { tag: "str", val: "not a channel" } };
   766→      case "send":
   767→        if (args[0] && args[0].tag === "chan") {
   768→          const chan = this.channels[args[0].id];
   769→          if (chan) chan.buffer.push(args[1]);
   770→          return { tag: "void" };
   771→        }
   772→        return { tag: "void" };
   773→
   774→      // ============================================================
   775→      // Phase 7: 20 Core Libraries
   776→      // ============================================================
   777→
   778→      // Cryptography & Encoding (6)
   779→      case "md5": {
   780→        const input = this.valueToString(args[0]);
   781→        const hash = crypto.createHash("md5").update(input).digest("hex");
   782→        return { tag: "str", val: hash };
   783→      }
   784→      case "sha256": {
   785→        const input = this.valueToString(args[0]);
   786→        const hash = crypto.createHash("sha256").update(input).digest("hex");
   787→        return { tag: "str", val: hash };
   788→      }
   789→      case "sha512": {
   790→        const input = this.valueToString(args[0]);
   791→        const hash = crypto.createHash("sha512").update(input).digest("hex");
   792→        return { tag: "str", val: hash };
   793→      }
   794→      case "base64_encode": {
   795→        const input = this.valueToString(args[0]);
   796→        const encoded = Buffer.from(input, "utf8").toString("base64");
   797→        return { tag: "str", val: encoded };
   798→      }
   799→      case "base64_decode": {
   800→        try {
   801→          const input = this.valueToString(args[0]);
   802→          const decoded = Buffer.from(input, "base64").toString("utf8");
   803→          return { tag: "ok", val: { tag: "str", val: decoded } };
   804→        } catch (e) {
   805→          return { tag: "err", val: { tag: "str", val: "invalid base64" } };
   806→        }
   807→      }
   808→      case "hmac": {
   809→        const message = this.valueToString(args[0]);
   810→        const secret = this.valueToString(args[1]);
   811→        const hmac = crypto.createHmac("sha256", secret).update(message).digest("hex");
   812→        return { tag: "str", val: hmac };
   813→      }
   814→
   815→      // JSON (4)
   816→      case "json_parse": {
   817→        try {
   818→          const jsonStr = this.valueToString(args[0]);
   819→          const obj = JSON.parse(jsonStr);
   820→          const value = this.jsonToValue(obj);
   821→          return { tag: "ok", val: value };
   822→        } catch (e) {
   823→          return { tag: "err", val: { tag: "str", val: `JSON parse error: ${String(e)}` } };
   824→        }
   825→      }
   826→      case "json_stringify": {
   827→        try {
   828→          const jsonStr = JSON.stringify(this.valueToJSON(args[0]), null, 0);
   829→          return { tag: "str", val: jsonStr };
   830→        } catch (e) {
   831→          return { tag: "err", val: { tag: "str", val: `JSON stringify error: ${String(e)}` } };
   832→        }
   833→      }
   834→      case "json_validate": {
   835→        try {
   836→          const jsonStr = this.valueToString(args[0]);
   837→          JSON.parse(jsonStr);
   838→          return { tag: "bool", val: true };
   839→        } catch {
   840→          return { tag: "bool", val: false };
   841→        }
   842→      }
   843→      case "json_pretty": {
   844→        try {
   845→          const jsonStr = this.valueToString(args[0]);
   846→          const obj = JSON.parse(jsonStr);
   847→          const pretty = JSON.stringify(obj, null, 2);
   848→          return { tag: "str", val: pretty };
   849→        } catch (e) {
   850→          return { tag: "err", val: { tag: "str", val: `JSON pretty error: ${String(e)}` } };
   851→        }
   852→      }
   853→
   854→      // Advanced Strings (3)
   855→      case "starts_with": {
   856→        if (args[0].tag === "str" && args[1].tag === "str") {
   857→          const result = args[0].val.startsWith(args[1].val);
   858→          return { tag: "bool", val: result };
   859→        }
   860→        return { tag: "bool", val: false };
   861→      }
   862→      case "ends_with": {
   863→        if (args[0].tag === "str" && args[1].tag === "str") {
   864→          const result = args[0].val.endsWith(args[1].val);
   865→          return { tag: "bool", val: result };
   866→        }
   867→        return { tag: "bool", val: false };
   868→      }
   869→      case "replace": {
   870→        if (args[0].tag === "str" && args[1].tag === "str" && args[2].tag === "str") {
   871→          const result = args[0].val.replaceAll(args[1].val, args[2].val);
   872→          return { tag: "str", val: result };
   873→        }
   874→        return args[0];
   875→      }
   876→
   877→      // Advanced Arrays (3)
   878→      case "reverse": {
   879→        if (args[0].tag === "arr") {
   880→          const reversed = [...args[0].val].reverse();
   881→          return { tag: "arr", val: reversed };
   882→        }
   883→        return args[0];
   884→      }
   885→      case "sort": {
   886→        if (args[0].tag === "arr") {
   887→          const sorted = [...args[0].val].sort((a, b) => {
   888→            const aVal = (a as any).val ?? 0;
   889→            const bVal = (b as any).val ?? 0;
   890→            return aVal < bVal ? -1 : aVal > bVal ? 1 : 0;
   891→          });
   892→          return { tag: "arr", val: sorted };
   893→        }
   894→        return args[0];
   895→      }
   896→      case "unique": {
   897→        if (args[0].tag === "arr") {
   898→          const seen = new Set<string>();
   899→          const unique: Value[] = [];
   900→          for (const item of args[0].val) {
   901→            const key = JSON.stringify(this.valueToJSON(item));
   902→            if (!seen.has(key)) {
   903→              seen.add(key);
   904→              unique.push(item);
   905→            }
   906→          }
   907→          return { tag: "arr", val: unique };
   908→        }
   909→        return args[0];
   910→      }
   911→
   912→      // Math (2)
   913→      case "gcd": {
   914→        const a = Math.abs((args[0] as any).val);
   915→        const b = Math.abs((args[1] as any).val);
   916→        const gcd = (x: number, y: number): number => (y === 0 ? x : gcd(y, x % y));
   917→        return { tag: "i32", val: gcd(a, b) };
   918→      }
   919→      case "lcm": {
   920→        const a = Math.abs((args[0] as any).val);
   921→        const b = Math.abs((args[1] as any).val);
   922→        const gcd = (x: number, y: number): number => (y === 0 ? x : gcd(y, x % y));
   923→        return { tag: "i32", val: (a * b) / gcd(a, b) };
   924→      }
   925→
   926→      // Utils (2)
   927→      case "uuid": {
   928→        const uuid = crypto.randomUUID();
   929→        return { tag: "str", val: uuid };
   930→      }
   931→      case "timestamp": {
   932→        const now = Date.now();
   933→        return { tag: "f64", val: now };
   934→      }
