   941→  // ============================================================
   942→  // 유틸리티
   943→  // ============================================================
   944→
   945→  private readI32(actor: Actor): number {
   946→    const b0 = this.chunk.code[actor.ip++];
   947→    const b1 = this.chunk.code[actor.ip++];
   948→    const b2 = this.chunk.code[actor.ip++];
   949→    const b3 = this.chunk.code[actor.ip++];
   950→    return b0 | (b1 << 8) | (b2 << 16) | (b3 << 24);
   951→  }
   952→
   953→  private readF64(actor: Actor): number {
   954→    const buf = new ArrayBuffer(8);
   955→    const bytes = new Uint8Array(buf);
   956→    for (let i = 0; i < 8; i++) bytes[i] = this.chunk.code[actor.ip++];
   957→    return new Float64Array(buf)[0];
   958→  }
   959→
   960→  private valueToString(v: Value): string {
   961→    switch (v.tag) {
   962→      case "i32": case "f64": return String(v.val);
   963→      case "str": return v.val;
   964→      case "bool": return v.val ? "true" : "false";
   965→      case "void": return "void";
   966→      case "none": return "None";
   967→      case "arr": return `[${v.val.map((e) => this.valueToString(e)).join(", ")}]`;
   968→      case "struct": {
   969→        const entries = [...v.fields.entries()].map(([k, val]) => `${k}: ${this.valueToString(val)}`);
   970→        return `{ ${entries.join(", ")} }`;
   971→      }
   972→      case "ok": return `Ok(${this.valueToString(v.val)})`;
   973→      case "err": return `Err(${this.valueToString(v.val)})`;
   974→      case "some": return `Some(${this.valueToString(v.val)})`;
   975→      case "chan": return `channel(${v.id})`;
   976→    }
   977→  }
   978→
   979→  private valuesEqual(a: Value, b: Value): boolean {
   980→    if (a.tag !== b.tag) return false;
   981→    if (a.tag === "void" && b.tag === "void") return true;
   982→    if (a.tag === "none" && b.tag === "none") return true;
   983→    if ("val" in a && "val" in b) return (a as any).val === (b as any).val;
   984→    return false;
   985→  }
   986→
   987→  private deepClone(v: Value): Value {
   988→    switch (v.tag) {
   989→      case "arr": return { tag: "arr", val: v.val.map((e) => this.deepClone(e)) };
   990→      case "struct": {
   991→        const fields = new Map<string, Value>();
   992→        for (const [k, val] of v.fields) fields.set(k, this.deepClone(val));
   993→        return { tag: "struct", fields };
   994→      }
   995→      case "ok": return { tag: "ok", val: this.deepClone(v.val) };
   996→      case "err": return { tag: "err", val: this.deepClone(v.val) };
   997→      case "some": return { tag: "some", val: this.deepClone(v.val) };
   998→      default: return v; // Copy 타입은 그대로
   999→    }
  1000→  }
  1001→
  1002→  // ============================================================
  1003→  // JSON Conversion (Phase 7)
  1004→  // ============================================================
  1005→
  1006→  private jsonToValue(obj: any): Value {
  1007→    if (obj === null) return { tag: "none" };
  1008→    if (typeof obj === "boolean") return { tag: "bool", val: obj };
  1009→    if (typeof obj === "number") return { tag: "i32", val: Math.floor(obj) };
  1010→    if (typeof obj === "string") return { tag: "str", val: obj };
  1011→    if (Array.isArray(obj)) {
  1012→      return { tag: "arr", val: obj.map((v) => this.jsonToValue(v)) };
  1013→    }
  1014→    if (typeof obj === "object") {
  1015→      const fields = new Map<string, Value>();
  1016→      for (const [k, v] of Object.entries(obj)) {
  1017→        fields.set(k, this.jsonToValue(v));
  1018→      }
  1019→      return { tag: "struct", fields };
  1020→    }
  1021→    return { tag: "void" };
  1022→  }
  1023→
  1024→  private valueToJSON(v: Value): any {
  1025→    switch (v.tag) {
  1026→      case "i32":
  1027→      case "f64":
  1028→        return v.val;
  1029→      case "bool":
  1030→        return v.val;
  1031→      case "str":
  1032→        return v.val;
  1033→      case "arr":
  1034→        return v.val.map((item) => this.valueToJSON(item));
  1035→      case "struct":
  1036→        const obj: any = {};
  1037→        for (const [k, val] of v.fields.entries()) {
  1038→          obj[k] = this.valueToJSON(val);
  1039→        }
  1040→        return obj;
  1041→      case "ok":
  1042→        return this.valueToJSON(v.val);
  1043→      case "err":
  1044→        return { error: this.valueToJSON(v.val) };
  1045→      case "some":
  1046→        return this.valueToJSON(v.val);
  1047→      case "none":
  1048→        return null;
  1049→      default:
  1050→        return null;
  1051→    }
  1052→  }
